<?php require 'audit_management.php'; exit; ?>
$locations=$db->query("SELECT location_id,MAX(project_location) project_location,MAX(location_size) location_size,MAX(date_planted) date_planted,MAX(dr_dp) dr_dp,COUNT(*) encoded_rows FROM grading_records GROUP BY location_id ORDER BY MAX(created_at) DESC")->fetchAll();$selected=$_GET['location']??($locations[0]['location_id']??'');$q=$db->prepare("SELECT v.code,v.name,g.grading_stage,COUNT(*) rows_count FROM grading_records g JOIN varieties v ON v.id=g.variety_id WHERE g.location_id=? GROUP BY v.id,g.grading_stage ORDER BY v.code");$q->execute([$selected]);$matrix=[];foreach($q as $r)$matrix[$r['code']][$r['grading_stage']]=$r['rows_count'];$varieties=$db->query('SELECT code,name FROM varieties ORDER BY code')->fetchAll();$stages=['01 GRADING','02 GRADING','03 GRADING','04 GRADING','HARVEST'];
?><!doctype html><html><head><meta charset="utf-8"><title>Audit Trail</title><link rel="stylesheet" href="style.css"></head><body><main><header><h1>PHILSURIN</h1><span><a href="index.php">ENCODING</a> <a href="report.php">REPORT</a> <a href="?logout=1">LOG OUT</a></span></header><section class="card"><h2>Audit Trail</h2><p class="hint">Select a saved Location ID to backtrack exactly which project and grading data were encoded.</p><table class="audit"><thead><tr><th>LOCATION ID</th><th>LOCATION OF PROJECT</th><th>SIZE OF LOCATION</th><th>DATE PLANTED</th><th>DR / DP</th><th>ENCODED ROWS</th></tr></thead><tbody><?php foreach($locations as $l):?><tr class="pick <?=($l['location_id']===$selected?'selected':'')?>" onclick="location.href='audit.php?location=<?=urlencode($l['location_id'])?>'"><td><?=e($l['location_id'])?></td><td><?=e($l['project_location'])?></td><td><?=e($l['location_size'])?></td><td><?=e($l['date_planted']?:'—')?></td><td><?=e($l['dr_dp']?:'—')?></td><td><?=e($l['encoded_rows'])?></td></tr><?php endforeach?></tbody></table></section><section class="card"><h2><?=e($selected?:'No location selected')?></h2><?php $current=array_values(array_filter($locations,function($x)use($selected){return $x['location_id']===$selected;}))[0]??null;if($current):?><p class="hint"><?=e($current['project_location'])?> · Size <?=e($current['location_size'])?> · Planted <?=e($current['date_planted']?:'—')?></p><a class="smallbtn" href="report.php?location=<?=urlencode($selected)?>">OPEN LOCATION REPORT</a><?php endif?><table class="matrix"><thead><tr><th>VARIETY</th><?php foreach($stages as $s):?><th><?=e(str_replace(' GRADING','',$s))?></th><?php endforeach?></tr></thead><tbody><?php foreach($varieties as $v):?><tr><td><?=e($v['code'].' '.$v['name'])?></td><?php foreach($stages as $s):?><td><?php if(isset($matrix[$v['code']][$s])):?><span class="check">✓</span><?php else:?><span class="empty">□</span><?php endif?></td><?php endforeach?></tr><?php endforeach?></tbody></table></section></main><style>.audit,.matrix{width:100%;border-collapse:collapse}.audit th,.audit td,.matrix th,.matrix td{border:1px solid #d7e0ea;padding:9px;text-align:left}.audit th,.matrix th{background:#dff2ea;color:#087f59;font-size:10px}.pick{cursor:pointer}.pick:hover,.pick.selected{background:#e4f6ee;font-weight:700}.matrix td:not(:first-child),.matrix th:not(:first-child){text-align:center}.check{display:inline-grid;place-items:center;width:16px;height:16px;border-radius:4px;background:#07865f;color:#fff;font-weight:bold}.empty{color:#bbc6d1;font-size:18px}.smallbtn{display:inline-block;background:#07865f;color:white;padding:9px 12px;border-radius:7px;text-decoration:none;font-weight:bold;font-size:10px;margin:8px 0 14px}</style></body></html>
